const app=document.querySelector('#app'),dialog=document.querySelector('#modal');
let popupTimer;
function scheduleMarketing(){
  clearTimeout(popupTimer);
  const video=document.querySelector('[data-hero-video]');
  if(video&&!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches){video.play?.().then(()=>{const b=document.querySelector('[data-action="hero-video"]');if(b)b.textContent=textFor(state,'Pause video');}).catch(()=>{video.controls=true;});}
  let seen={};try{seen=JSON.parse(localStorage.getItem('aelvo-popup-seen')||'{}');state.popupSeen=JSON.parse(sessionStorage.getItem('aelvo-popup-visit')||'{}');}catch{}
  if(!popupEligible(state,route,Date.now(),seen))return;
  const at=route;
  popupTimer=setTimeout(()=>{
    if(route!==at||dialog.open||state.assistantOpen||!popupEligible(state,route,Date.now(),seen))return;
    state.popupSeen??={};state.popupSeen[state.saved.popup.revision]=true;
    try{sessionStorage.setItem('aelvo-popup-visit',JSON.stringify(state.popupSeen));localStorage.setItem('aelvo-popup-seen',JSON.stringify({ever:true,day:new Date().toISOString().slice(0,10)}));}catch{}
    modal('AELVO',popupContent(state));
  },state.saved.popup.delay*1000);
}
let route='/',params=new URLSearchParams(),toastTimer,otpTimer,quickId=null,pendingOTP=null;
const today=()=>new Date().toISOString().slice(0,10);
const log=(action,module)=>state.audit.push({time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),actor:currentStaff(state)?.name||'Demo Admin',action,module});
function toast(text,to=''){text=route.startsWith('/admin')?text:textFor(state,text);const t=document.querySelector('#toast');t.textContent=text;if(!to&&/verified|created/i.test(text))t.innerHTML=`<span class="verified-toast">${icon('check')}<span>${E(text)}</span></span>`;if(to)t.innerHTML=`<a href="#${to}" class="toast-link"><span>${E(text)}</span><strong>View bag</strong></a>`;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),to?6500:3600);}
function flyToBag(src,rect){if(!rect||!document.body||window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches)return;const mobile=document.querySelector('.center-bag'),header=document.querySelector('.header-actions a[href="#/cart"]');const target=mobile?.getBoundingClientRect().width?mobile:header;if(!target)return;const end=target.getBoundingClientRect(),img=document.createElement('img');img.src=src;img.alt='';img.className='flying-product';Object.assign(img.style,{left:rect.left+'px',top:rect.top+'px',width:Math.min(rect.width,90)+'px',height:Math.min(rect.height,90)+'px'});document.body.append(img);const animation=img.animate?.([{transform:'translate(0,0) scale(1)',opacity:.9},{transform:`translate(${end.left-rect.left}px,${end.top-rect.top}px) scale(.2)`,opacity:.15}],{duration:650,easing:'cubic-bezier(.3,.7,.4,1)'});if(animation)animation.onfinish=()=>img.remove();else img.remove();}
function navigate(to){state.searchOpen=false;closeModal();state.adminMenu=false;if(location.hash==='#'+to)render();else location.hash=to;}
function closeModal(){if(dialog.open)dialog.close();quickId=null;clearInterval(otpTimer);}
function modal(title,body){if(!route.startsWith('/admin')){title=textFor(state,title);body=localizeMarkup(body,state);}dialog.style.width=quickId?'min(960px,calc(100vw - 30px))':'';dialog.innerHTML=`<div class="modal-head"><h2 id="modal-title">${E(title)}</h2>${button(icon('close'),'close-modal','','icon-btn')}</div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function formModal(title,kind,body,attributes='',submit='Save demo record'){modal(title,`<form data-form="${kind}" ${attributes}>${body}<div class="error-text" data-error></div><div class="form-actions">${button('Cancel','close-modal','','btn secondary')}<button class="btn" type="submit">${E(submit)}</button></div></form>`)}
function values(form){const v={};for(const [k,x] of new FormData(form))if(typeof x==='string'&&!['password','confirm','secret','dbPassword'].includes(k))v[k]=x;for(const input of form.querySelectorAll('input[type=checkbox]'))v[input.name]=input.checked;return v;}
function fail(form,message){let e=form?.querySelector('[data-error]');if(e){e.textContent=route.startsWith('/admin')?message:textFor(state,message);if(!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches)e.animate?.([{transform:'translateX(0)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:180});e.scrollIntoView({block:'nearest'});}else toast(message)}
function success(message,module='Preview'){log(message,module);closeModal();render();toast(message+' · Preview only');}
function formInput(name,form){return form?.elements.namedItem(name);}
function selectionOptions(){return state.products.flatMap(p=>p.variants.map(v=>[p.id+'::'+v.size+'::'+(v.color||''),variantLabel(p,v.size,v.color)]));}
function chosen(value){const [id,size,color]=value.split('::');const product=state.products.find(p=>p.id===id),variant=variantFor(product,size,color);if(!product||!variant)throw Error('Choose a valid product variant.');return {product,variant,id,size,color:colour(product,color).id};}
function numeric(v,label,min=0){const n=Number(v);if(!Number.isFinite(n)||n<min)throw Error(label+' is invalid.');return n;}
const fileOf=(form,name)=>form.elements.namedItem(name)?.files?.[0];
const moduleFor=t=>({stock:'inventory',expenses:'accounts',staff:'team',redirects:'seo',pages:'content'}[t]||t);
function guardAction(a,t){const map={'order-status':['orders','edit'],'order-payment':['payments','create'],'courier-book':['courier','create'],'manual-add':['manual','create'],'manual-remove':['manual','create'],'manual-clear':['manual','create'],'transfer':['accounts','edit'],'add-funds':['accounts','edit'],'balance-adjust':['accounts','edit'],'inventory-adjust':['inventory','edit'],'inspect-return':['returns','edit'],'restock-return':['returns','edit'],'refund-review':['returns','edit'],'customer-note':['customers','edit'],'delete-coupon':['coupons','delete'],'delete-redirect':['seo','delete'],'reset-seo':['seo','edit'],'new-role':['team','edit'],'staff-permissions':['team','edit']};if(a==='new-record')requirePermission(state,moduleFor(t.dataset.type),'create');else if(a==='record-detail')requirePermission(state,moduleFor(t.dataset.type),'view');else if(map[a])requirePermission(state,...map[a]);}
function guardForm(kind,form){let rule={record:[moduleFor(form.dataset.type),form.dataset.id?'edit':'create'],'order-status':['orders','edit'],'order-note':['orders','edit'],'order-payment':['payments','create'],'courier-book':['courier','create'],'manual-add':['manual','create'],'manual-sale':['manual','create'],transfer:['accounts','edit'],'add-funds':['accounts','edit'],'balance-adjust':['accounts','edit'],'inventory-adjust':['inventory','edit'],'advance-review':['payments','edit'],settlement:['payments','edit'],'inspect-return':['returns','edit'],'restock-return':['returns','edit'],'refund-review':['returns','edit'],'customer-note':['customers','edit'],'risk-review':['customers','edit'],'page-editor':['content','edit'],banner:['coupons','edit'],'delete-coupon':['coupons','delete'],'delete-redirect':['seo','delete'],permissions:['team','edit'],'staff-permissions':['team','edit'],'new-role':['team','create']}[kind];if(kind==='config')rule=[form.dataset.section?.startsWith('seo')?'seo':'settings','edit'];if(rule)requirePermission(state,...rule);}
function ownerOnly(){if((state.previewRole||'Super Admin')!=='Super Admin'||state.previewStaff)throw Error('Only the owner controls roles and staff permissions.');}
function storeCheckout(){const f=document.querySelector('#checkout-form');if(f)state.checkoutDraft=values(f);}
function otp(phone,purpose,payload={}){if(!validPhone(phone))throw Error('Enter a valid Bangladesh mobile number.');pendingOTP={phone:normalizePhone(phone),purpose,payload,expires:Date.now()+120000,attempts:0,lastSent:Date.now(),resends:0};showOTP();}
function showOTP(){const p=pendingOTP;formModal('Verify your number','otp',`<p>Verification for ${E(p.phone.slice(0,3)+'•••••'+p.phone.slice(-3))}</p>${notice('Demo code: <strong>123456</strong>. No SMS is sent. The code expires after 2 minutes.')}${field('6-digit code','code','','text','required pattern="[0-9]{6}" inputmode="numeric" maxlength="6" autocomplete="one-time-code" class="otp-input"')}<div class="between mt"><span class="small muted" id="otp-timer">Resend available in 30s</span>${button('Resend','otp-resend','disabled','text-link')}</div>`,'','Verify');otpTimer=setInterval(()=>{if(!dialog.open||!pendingOTP){clearInterval(otpTimer);return;}const sec=Math.max(0,30-Math.floor((Date.now()-pendingOTP.lastSent)/1000));const b=dialog.querySelector('[data-action="otp-resend"]'),t=dialog.querySelector('#otp-timer');if(b)b.disabled=sec>0||pendingOTP.resends>=3;if(t)t.textContent=sec?'Resend available in '+sec+'s':pendingOTP.resends>=3?'Resend limit reached':'You can resend now';},1000);}
export function render(){if(!state.language){try{state.language=localStorage.getItem('aelvo-language')==='bn'?'bn':'en';}catch{state.language='en';}}initEngagement(state);applyTheme(state);const raw=location.hash.replace(/^#/,'')||'/';const [pathname,query='']=raw.split('?');route=pathname.startsWith('/')?pathname:'/'+pathname;params=new URLSearchParams(query);if(route!=='/checkout')state.buyNow=null;const isAdmin=route.startsWith('/admin');if(document.documentElement)document.documentElement.lang=isAdmin?'en':state.language;if(route.startsWith('/install'))app.innerHTML=installer(state);else if(isAdmin)app.innerHTML=adminShell(adminView(route,state),state,route);else app.innerHTML=storeShell(storefront(route,params,state),state,route);const messages=document.querySelector('#assistant-messages');if(messages)messages.scrollTop=messages.scrollHeight;document.title=(isAdmin?'Admin · ':route==='/checkout'?'Checkout · ':'')+'AELVO Fashion · Preview';scheduleMarketing();if(quickId){const p=state.products.find(p=>p.id===quickId);if(p)modal('Quick view',productDetail(p,state,true));} }
window.addEventListener('hashchange',()=>{state.searchOpen=false;state.assistantOpen=false;closeModal();state.qty=1;state.adminMenu=false;render();window.scrollTo({top:0,behavior:'instant'});});
dialog.addEventListener('click',e=>{if(e.target===dialog&&e.offsetX>=dialog.clientWidth)closeModal();});
dialog.addEventListener('cancel',()=>{quickId=null;clearInterval(otpTimer)});

function recordForm(type,id,from=''){const list=type==='products'?state.products:state.records[type]||[],r=list.find(r=>r.id===id);let body='',title=(r?'Edit ':'New ')+type,submit='Save draft';
switch(type){case'products':body=productEditor(r);submit='Save product';break;
case'stock':title='Stock entry';body=`${select('Variant','variant',selectionOptions())}${select('Movement type','type',!can(state,'inventory','edit')?['Purchase receipt']:['Purchase receipt','Opening stock','Adjustment in','Damage / write-off'])}${field('Quantity','qty','1','number','required min="1" step="1"')}${field('Reference','reference',from||'','text','required placeholder="PO-0042 or adjustment reference"')}${textarea('Reason / notes','note','','required')}${notice('Posting updates the variant ledger once. Reserved units cannot be written off as available stock.')}<label class="choice"><input type="radio" name="intent" value="draft" checked>Save as draft</label><label class="choice"><input type="radio" name="intent" value="post">Post demo movement</label>`;submit='Save stock entry';break;
case'purchases':if(r){modal(r.id,`<p>${E(r.supplier)}</p>${table(['Total','Paid','Due','Receiving'],[[money(r.total),money(r.paid),money(r.total-r.paid),E(r.status)]])}${fileLink(r.slip)}${notice('Recording a purchase does not receive inventory. Use Stock Entry when items are physically received.')}<div class="mt">${button('Receive stock','new-record','data-type="stock" data-from="'+r.id+'"','btn')}</div>`);return;}body=`${select('Supplier','supplier',state.records.suppliers.map(s=>s.name))}${select('Variant','variant',selectionOptions())}<div class="field-grid">${field('Quantity','qty','20','number','required min="1" step="1"')}${field('Unit purchase cost','cost','2800','number','required min="0" step="0.01"')}${field('Discount','discount','2000','number','min="0"')}${field('Shipping / import cost','shipping','2000','number','min="0"')}${field('Other costs','other','400','number','min="0"')}</div>${fileField('Purchase slip','purchaseSlip',true)}${notice('Saved as a draft with no supplier payment and no inventory receipt.')}`;break;
case'suppliers':body=`${field('Supplier name','name',r?.name||'','text','required')}${field('Phone','phone',r?.phone||'','tel')}${textarea('Address / notes','notes',r?.notes||'')}`;submit='Save supplier';break;
case'expenses':body=`${field('Category','category',r?.category||'','text','required')}${field('Amount','amount',r?.amount||'','number','required min="0.01" step="0.01"')}${select('Payment account','account',Object.keys(state.accounts),r?.account||'Cash')}${select('Status','status',['Draft','Posted'],r?.status||'Draft')}${field('Date','date',r?.date||today(),'date','required')}${field('Receipt (optional)','receipt','','file','accept="image/*,.pdf"')}${r?.status==='Posted'?notice('Posted expenses are shown read-only. Corrections use an audited adjustment in the backend phase.'):''}`;if(r?.status==='Posted'){modal('Posted expense',body);return;}submit='Save expense';break;
case'customers':body=`${field('Name','name',r?.name||'','text','required')}${field('Phone','phone',r?.phone||'','tel','required')}${notice('This creates a contact record only. It does not create an authenticated or phone-verified customer account.')}`;submit='Save customer contact';break;
case'coupons':title=r?'Coupon Editor':'Create promotion';body=`<div class="field-grid">${field('Code / internal identifier','id',r?.id||'','text','required pattern="[A-Za-z0-9_-]+"')}${field('Internal name','name',r?.name||'','text','required')}${select('Method','method',['Code','Automatic','Free shipping'],r?.method||'Code')}${field('Percentage value','value',r?.value??10,'number','min="0" max="100"')}${field('Maximum discount','cap',r?.cap??500,'number','min="0"')}${field('Minimum subtotal','min',r?.min??2000,'number','min="0"')}${field('Total limit','limit',r?.limit??200,'number','min="1" step="1"')}${field('Per-customer limit','perCustomer',r?.perCustomer??1,'number','min="1" step="1"')}</div>${select('Applies to','applies',['All products','Shoes','Bags','Wallets','Socks','Belts'],r?.applies||'All products')}${select('Status','status',['Draft','Active','Scheduled','Paused'],r?.status||'Draft')}${field('Start date','start',r?.start||'2026-10-10','date')}${field('End date','end',r?.end||'2026-10-31','date')}${checkbox('Allow compatible offer stacking','stacking',false)}${notice('This editor saves draft rule examples. Checkout uses fixed demo offers: AELVO10 (10%, minimum ৳2,000, maximum ৳500) and SHIPFREE. Editing these drafts does not change checkout pricing yet.')}`;submit='Save promotion preview';break;
case'pages':body=`${field('Page title','name','','text','required')}${field('Slug','slug','','text','required placeholder="new-page"')}`;break;
case'staff':body=staffEditor(state,r);submit='Save staff profile';break;
case'redirects':body=`${field('Source path','from',r?.from||from||'','text','required placeholder="/old-page"')}${field('Destination path','to',r?.to||'','text','required placeholder="/new-page"')}${select('HTTP status','type',['301','302'],r?.type||'301')}`;submit=r?'Save redirect':'Add redirect';break;
case'returns':body=`${field('Order reference','order','','text','required')}${select('Product','product',state.products.map(p=>p.name))}${field('Quantity','qty','1','number','required min="1" step="1"')}${field('Refundable paid amount','amount','','number','required min="0"')}${textarea('Return reason','reason','','required')}`;submit='Create return request';break;
case'payments':modal(r?.id||'Payment',`${table(['Order','Method','Amount','Verification','Settlement'],[[E(r?.order),E(r?.method),money(r?.amount),E(r?.status),E(r?.settlement)]])}<div class="mt">${link('Open advance review','/admin/payments/advances','btn secondary')}</div>`);return;
default:modal('Record details',notice('Select a record from the current module.'));return;}
formModal(title,'record',body,`data-type="${type}" data-id="${E(id||'')}"`,submit);}

document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;e.preventDefault();const a=target.dataset.action,id=target.dataset.id;try{guardAction(a,target);switch(a){
case'open-search':state.searchTop=document.querySelector('.store-header')?.getBoundingClientRect?.().bottom;state.searchOpen=true;render();document.querySelector('#header-query')?.focus?.();break;
case'close-search':state.searchOpen=false;render();document.querySelector('[data-action="open-search"]')?.focus?.();break;
case'assistant-open':if(!state.websiteConversation)newWebsiteConversation(state);state.assistantOpen=true;render();break;
case'assistant-close':state.assistantOpen=false;render();break;
case'assistant-prompt':receiveCustomerMessage(state,target.dataset.text);state.assistantOpen=true;render();break;
case'assistant-handoff':{const c=state.support.conversations.find(c=>c.id===state.websiteConversation)||newWebsiteConversation(state);if(c.mode!=='human')handoff(state,c);state.assistantOpen=true;render();break;}
case'assistant-product':{const p=state.products.find(p=>p.id===id);if(!p||p.archived||p.status!=='Active')throw Error('This product is unavailable.');const options=p.variants.filter(v=>available(p,v.size,v.color)>0);if(!options.length)throw Error('This product is currently unavailable.');formModal('Choose '+p.name,'assistant-cart',`${select('Colour & size','variant',options.map(v=>[p.id+'::'+v.size+'::'+v.color,colour(p,v.color).name+' · '+v.size]))}${field('Quantity','qty','1','number','required min="1" step="1"')}`,'','Add to bag');break;}
case'support-take':{const c=supportRecord(state,id);if(!currentStaff(state))throw Error('Choose a staff profile using Preview access before taking a conversation.');if(c.assignee&&c.assignee!==currentStaff(state)?.id)throw Error('This conversation is assigned. Ask the owner to reassign it.');c.assignee=currentStaff(state).id;c.mode='human';c.status='Assigned';log('Conversation '+id+' taken','Support');render();break;}
case'support-resolve':{const c=supportRecord(state,id);assertAssignee(state,c);c.status='Resolved';log('Conversation '+id+' resolved','Support');render();break;}
case'support-resume':{const c=supportRecord(state,id);assertAssignee(state,c);c.mode='assistant';c.status='Open';c.assignee=null;c.messages.push({role:'system',text:'The support agent resumed catalogue assistance.'});log('Assistant resumed for '+id,'Support');render();break;}
case'social-login':modal(target.dataset.provider+' sign-in',notice('This sign-in method is not connected yet. Use your mobile number to create or open an account.'));break;
case'theme-preset':requirePermission(state,'settings','edit');state.saved['settings-theme']={...themes[target.dataset.value]};render();toast('Theme applied');break;
case'variant-delete':{requirePermission(state,'inventory','delete');const p=state.products.find(p=>p.id===id),v=variantFor(p,target.dataset.size,target.dataset.color);if(v.onHand||v.reserved)throw Error('Adjust or move this variant’s stock to zero before deleting it.');formModal('Delete variant','variant-delete',notice(E(variantLabel(p,v.size,v.color))+'. This zero-stock variant will leave the active catalogue.'),`data-id="${id}" data-size="${E(v.size)}" data-color="${E(v.color)}"`,'Delete variant');break;}
case'variant-restore':requirePermission(state,'inventory','edit');variantFor(state.products.find(p=>p.id===id),target.dataset.size,target.dataset.color).archived=false;success('Variant restored','Inventory');break;
case'audit-view':requirePermission(state,'audit');modal('Audit entry',recordDetails(state.audit[Number(target.dataset.index)]));break;
case'manage-view':{requirePermission(state,recordModule(target.dataset.type));const r=recordFor(state,target.dataset.type,id);if(target.dataset.type==='purchases'){recordForm('purchases',id);break;}if(target.dataset.type==='pages'){modal('Page preview · '+r.name,`<p class="eyebrow">${E(r.status)}</p><h2>${E(r.name)}</h2><div class="reading mt">${E(r.content||'No page content yet.').replaceAll('\n','<br>')}</div>`);break;}modal('View · '+id,recordDetails(r));break;}
case'manage-edit':{const type=target.dataset.type;requirePermission(state,recordModule(type),'edit');const r=recordFor(state,type,id);if(type==='pages'){navigate('/admin/content/'+id);break;}if(type==='orders'){formModal('Edit order · '+id,'order-contact',`${field('Customer','customer',r.customer,'text','required')}${field('Phone','phone',r.phone,'tel')}${textarea('Delivery address','address',r.address,'required')}${textarea('Note','note',r.note||'')}`,`data-id="${id}"`);break;}if(['payments','purchases','returns','movements'].includes(type)||(type==='expenses'&&r.status==='Posted')){formModal('Edit details · '+id,'record-annotation',annotationForm(r),`data-type="${type}" data-id="${id}"`);break;}recordForm(type,id);break;}
case'manage-delete':{const type=target.dataset.type;requirePermission(state,recordModule(type),'delete');const r=recordFor(state,type,id);formModal('Delete · '+id,'record-delete',`${notice('Remove this record from active lists. Financial and stock history stays intact; it can be restored from Archived records.')}${textarea('Reason','reason','','required')}`,`data-type="${type}" data-id="${id}"`,'Delete record');break;}
case'manage-restore':restoreRecord(state,target.dataset.type,id);success('Record restored',target.dataset.type);break;
case'close-modal':closeModal();break;case'rerender':render();break;case'print':window.print();break;
case'shop-category':state.category=target.dataset.value;state.query='';navigate('/shop'+(state.category==='All'?'':'?category='+encodeURIComponent(state.category)));break;
case'buy-now-select':case'quick-view':quickId=id;state.qty=1;state.color=colours(state.products.find(p=>p.id===id))[0].id;state.productPhoto=0;state.size=state.products.find(p=>p.id===id).variants[0].size;modal('Quick view',productDetail(state.products.find(p=>p.id===id),state,true));dialog.style.width='min(960px,calc(100vw - 30px))';break;
case'select-size':state.size=target.dataset.value;render();break;
case'select-colour':state.color=target.dataset.color;state.productPhoto=0;state.qty=1;render();break;
case'product-photo':state.productPhoto=Number(target.dataset.index);render();break;
case'product-qty':state.qty=Math.max(1,Math.min(99,state.qty+Number(target.dataset.delta)));if(quickId)render();else{const q=document.querySelector('#product-qty');if(q)q.textContent=state.qty;}break;
case'set-language':storeCheckout();state.language=target.dataset.value==='bn'?'bn':'en';try{localStorage.setItem('aelvo-language',state.language);}catch{}render();break;
case'buy-now':startBuyNow(state,id,target.dataset.size,target.dataset.color,state.qty);navigate('/checkout');break;
case'hero-video':{const video=document.querySelector('#home-hero-video');if(video){if(video.paused)video.play().then(()=>{target.textContent=textFor(state,'Pause video');}).catch(()=>toast('Video playback is unavailable.'));else{video.pause();target.textContent=textFor(state,'Play video');}}break;}
case'owner-ai-send':ownerOnly();toast('Owner email delivery requires the PHP authentication and email connection. No code was sent.');break;
case'review-moderate':{requirePermission(state,'products','edit');const r=state.reviews?.find(x=>x.id===id);if(!r)throw Error('Review not found.');formModal('Review moderation','review-moderation',`<blockquote>${E(r.body)}</blockquote><div class="review-photos">${r.photos.map(f=>`<img src="${E(f.url)}" alt="Customer review photo">`).join('')}</div>${select('Visibility','status',['Pending','Published','Hidden',...(can(state,'products','delete')?['Removed']:[])],r.status)}${textarea('Public shop reply','reply',r.reply||'','maxlength="2000"')}${textarea('Moderation reason','reason','','required maxlength="500"')}`,`data-id="${id}"`,'Save moderation');break;}
case'add-cart':{const origin=target.closest?.('.product-detail,.product-card')?.querySelector('img'),rect=origin?.getBoundingClientRect?.(),src=origin?.src;addCart(state.cart,state.products,id,target.dataset.size,state.qty,target.dataset.color);closeModal();render();toast('Added to your bag','/cart');if(src)flyToBag(src,rect);break;}
case'wishlist':state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];render();toast(state.wishlist.includes(id)?'Saved to your wishlist':'Removed from wishlist');break;
case'cart-remove':state.cart.splice(Number(target.dataset.index),1);render();break;
case'cart-qty':{const i=Number(target.dataset.index),r=state.cart[i],next=r.qty+Number(target.dataset.delta);if(next<1)state.cart.splice(i,1);else if(next<=available(state.products.find(p=>p.id===r.id),r.size,r.color))r.qty=next;else throw Error('That quantity is not available.');render();break;}
case'size-guide':modal('Find your fit',`${table(['EU size','Sample foot length'],[['40','25.0 cm'],['41','25.7 cm'],['42','26.4 cm'],['43','27.1 cm']])}${notice('Illustrative size guide only. Actual supplier measurements and fit information must be verified before launch.')}`);break;
case'demo-login':state.user={name:'Rahim Ahmed',phone:'01700007788',email:'rahim@example.com',verified:true};navigate('/account');toast('Signed in to the verified demo account');break;
case'logout':state.user=null;state.verifiedCheckoutPhone=null;navigate('/signin');break;
case'checkout-otp':{storeCheckout();const phone=state.checkoutDraft?.phone;if(!validPhone(phone))throw Error('Enter a valid Bangladesh mobile number first.');if(!needsOTP(state.user,phone,state.verifiedCheckoutPhone)){render();break;}otp(phone,'checkout');break;}
case'otp-resend':if(Date.now()-pendingOTP.lastSent<30000)throw Error('Please wait for the resend timer.');if(pendingOTP.resends>=3)throw Error('Resend limit reached. Start verification again.');pendingOTP.lastSent=Date.now();pendingOTP.expires=Date.now()+120000;pendingOTP.attempts=0;pendingOTP.resends++;toast('Demo code refreshed: 123456');break;
case'new-address':case'edit-address':{const i=Number(target.dataset.index),v=state.addresses[i]||{};formModal('Delivery address','address',`${field('Label','label',v.label||'Home','text','required')}${textarea('Address','address',v.address||'','required')}${field('Phone','phone',v.phone||'','tel','required')}`,`data-index="${a==='edit-address'?i:-1}"`,'Save address');break;}
case'admin-menu':state.adminMenu=!state.adminMenu;render();break;case'reset-role':state.previewRole='Super Admin';state.previewStaff=null;navigate('/admin');break;
case'notifications':modal('Needs attention',`${link('1 advance payment awaiting review','/admin/payments/advances','list-link')}${link('1 return inspection passed','/admin/returns','list-link')}${link('৳50 courier settlement difference','/admin/payments/settlement','list-link')}`);break;
case'new-record':recordForm(target.dataset.type,null,target.dataset.from||'');break;case'record-detail':recordForm(target.dataset.type,id);break;
case'order-status':{const o=state.orders.find(o=>o.id===id);formModal('Update order status','order-status',select('Status','status',['Pending','Processing','Packed','Courier Booked','In Transit','Delivered','Cancelled','Failed Delivery'],o.status)+textarea('Reason','reason','','required')+notice('Changing fulfilment does not automatically verify payment, restock returns or issue refunds.'),`data-id="${id}"`,'Update demo status');break;}
case'order-payment':{const o=state.orders.find(o=>o.id===id);formModal('Record verified demo payment','order-payment',`${field('Amount','amount','','number',`required min="0.01" max="${o.total-o.paid}" step="0.01"`)}${select('Destination account','account',Object.keys(state.accounts),'bKash')}${field('Verified reference','reference','','text','required placeholder="DEMO-RECEIPT"')}${checkbox('I reviewed the sample merchant receipt.','verified')}${notice('The remaining COD will decrease only after this demo verification.')}`,`data-id="${id}"`,'Record demo payment');break;}
case'track-order':navigate('/tracking?id='+id);break;
case'courier-book':{const o=state.orders.find(o=>o.id===id);if(o.courier!=='Not booked'){modal('Courier review',`<p>${E(o.id)} · ${E(o.courier)}</p>${notice('Current status: '+E(o.status)+'. No live courier request is made.')}<div class="mt">${link('View order','/admin/orders/'+id)}</div>`);break;}if(o.status==='Awaiting Advance Payment')throw Error('Verify the required advance before booking.');if(['Cancelled','Delivered','Draft'].includes(o.status))throw Error('This order is not eligible for booking.');formModal('Courier booking preview','courier-book',`${field('Order','order',id,'text','readonly')}${field('COD to collect','cod',o.total-o.paid,'number','readonly')}${textarea('Delivery address','address',o.address,'required')}${notice('This creates a DEMO consignment only. Booking does not mark an order dispatched or delivered.')}`,`data-id="${id}"`,'Simulate booking');break;}
case'manual-add':{const p=state.products.find(p=>p.id===id);formModal('Add '+p.name,'manual-add',`${select('Variant','variant',p.variants.map(v=>[p.id+'::'+v.size+'::'+(v.color||''),colour(p,v.color).name+' · '+v.size]))}${field('Quantity','qty','1','number','required min="1" step="1"')}`,`data-id="${id}"`,'Add to sale');break;}
case'manual-remove':state.manual.splice(Number(target.dataset.index),1);render();break;case'manual-clear':state.manual=[];render();break;
case'inventory-history':{const p=state.products.find(p=>p.id===id),v=variantFor(p,target.dataset.size,target.dataset.color);modal('Variant stock',`${table(['Product','Variant','On hand','Reserved','Available'],[[E(p.name),E(v.size),v.onHand,v.reserved,v.onHand-v.reserved]])}<div class="mt">${link('Open movement history','/admin/inventory/movements','btn secondary')}</div>`);break;}
case'transfer':formModal('Transfer funds','transfer',`${select('From account','from',Object.keys(state.accounts),'Cash')}${select('To account','to',Object.keys(state.accounts),'Bank')}${field('Amount','amount','10000','number','required min="0.01" step="0.01"')}${field('Reference','reference','','text','required')}${textarea('Explanation','explanation','','required placeholder="Why are these funds moving?"')}${fileField('Supporting document','document')}${notice('A transfer moves available funds between accounts. It does not create revenue or expense. Fee: ৳0 in this example.')}`,'','Transfer demo funds');break;
case'add-funds':formModal('Add funds','add-funds',`${select('Account','account',Object.keys(state.accounts))}${field('Amount','amount','','number','required min="0.01" step="0.01"')}${select('Source','source',['Owner funds','Opening balance','Other non-sales receipt'])}${field('Reference','reference','','text','required')}${textarea('Explanation','explanation','','required placeholder="Where did these funds come from?"')}${fileField('Supporting document','document')}`,'','Add demo funds');break;
case'inspect-return':{const r=state.records.returns.find(r=>r.id===id);formModal('Return inspection','inspect-return',`${field('Received quantity','qty',r.qty,'number',`required min="0" max="${r.qty}" step="1"`)}${select('Condition','condition',['Sellable','Damaged','Wrong item'])}${textarea('Inspection note','note','','required')}${notice('Inspection does not automatically restock the item or pay a refund.')}`,`data-id="${id}"`,'Record inspection');break;}
case'restock-return':{const r=state.records.returns.find(r=>r.id===id);if(r.status!=='Inspection passed')throw Error('Receive and inspect the sellable item first.');if(r.restock==='Completed')throw Error('This return has already been restocked.');const p=state.products.find(p=>p.name===r.product);if(!p)throw Error('The product needs to be linked to a stock variant.');formModal('Review restock','restock-return',`${select('Variant','variant',p.variants.map(v=>[p.id+'::'+v.size+'::'+(v.color||''),variantLabel(p,v.size,v.color)]))}${notice('Add '+r.qty+' inspected sellable unit(s) to the ledger once. Refund status is unchanged.')}`,`data-id="${id}"`,'Post demo restock');break;}
case'refund-review':{const r=state.records.returns.find(r=>r.id===id);formModal('Refund review','refund-review',`${field('Proposed refund','amount',r.amount,'number',`required min="0.01" max="${r.amount}" step="0.01"`)}${select('Source account','account',Object.keys(state.accounts),'bKash')}${textarea('Reason','reason','','required')}${notice('Verified original paid amount: '+money(r.amount)+'. Current state: '+E(r.refund)+'. Approval is separate from execution; this action does not send money.')}`,`data-id="${id}"`,'Approve demo refund');break;}
case'customer-note':{const c=state.records.customers.find(c=>c.id===id);formModal('Customer note','customer-note',textarea('Internal note','note',c.note||'','required'),`data-id="${id}"`,'Save note');break;}
case'export':downloadCSV(target.dataset.type);break;case'report-range':toast('Fixed sample period shown. Live date aggregation belongs to the report engine.');break;
case'page-preview':{const p=state.records.pages.find(p=>p.id===id),f=document.querySelector('[data-form="page-editor"]'),v=f?values(f):p;modal('Private page preview',`<p class="eyebrow">Unpublished preview</p><h2>${E(v.name||p.name)}</h2><div class="reading mt">${E(v.content||p.content||'No content yet.').split('\n').map(t=>t?'<p>'+t+'</p>':'').join('')}</div>`);break;}
case'banner-select':toast(target.dataset.value+' is another sample banner. The Footwear edit is editable in this preview.');break;
case'delete-redirect':formModal('Remove redirect','delete-redirect',notice('Remove this rule from the demo redirect list?'),`data-id="${id}"`,'Remove rule');break;
case'reset-seo':delete state.saved[target.dataset.section];render();toast('Overrides reset to defaults');break;
case'sitemap-download':{const paths=['/',...state.products.map(p=>'/product/'+p.id),...state.records.pages.filter(p=>p.status==='Published').map(p=>'/'+p.id)];download('aelvo-sample-sitemap.xml','application/xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(p=>'<url><loc>https://aelvo.example'+E(p)+'</loc></url>').join('')+'</urlset>');break;}
case'backup-download':download('aelvo-demo-snapshot.json','application/json',JSON.stringify({label:'Frontend demo snapshot — not a production backup',products:state.products,orders:state.orders,records:state.records,accounts:state.accounts},null,2));break;
case'integration-info':modal('Integration setup',`<p>During backend integration:</p><div class="timeline">${['Choose the merchant / service account','Store credentials on the server','Test a sandbox request and callback','Verify idempotency, errors and reconciliation','Enable the service after validation'].map(t=>`<div class="timeline-step"><span class="timeline-dot"></span><div>${t}</div></div>`).join('')}</div>${notice('Current connection: not configured. No provider request was sent.')}`);break;
case'add-colour':{const container=dialog.querySelector('#product-colours'),rows=container.querySelectorAll('[data-colour-row]'),index=rows.length?Math.max(...[...rows].map(r=>Number(r.dataset.index)))+1:0;container.insertAdjacentHTML('beforeend',colourRow({},index));break;}
case'remove-colour':target.closest('[data-colour-row]')?.remove();break;
case'inventory-adjust':{const p=state.products.find(p=>p.id===id),v=variantFor(p,target.dataset.size,target.dataset.color);formModal('Edit stock · '+p.name,'inventory-adjust',`<p class="mb">${E(colour(p,v.color).name+' · '+v.size)}</p>${field('Counted on-hand quantity','onHand',v.onHand,'number',`required min="${v.reserved}" step="1"`)}${textarea('Reason for correction','reason','','required')}${notice('Reserved: '+v.reserved+'. An adjustment records the old and new quantities; it does not erase history.')}`,`data-id="${id}" data-size="${E(v.size)}" data-color="${E(v.color||'')}"`,'Post stock correction');break;}
case'balance-adjust':formModal('Correct account balance','balance-adjust',`${select('Account','account',Object.keys(state.accounts),'Cash','id="balance-account"')}${field('Correct balance','balance',state.accounts.Cash,'number','required min="0" step="0.01"')}${textarea('Reason for correction','explanation','','required')}${fileField('Supporting document','document')}${notice('The difference is posted as a balance adjustment. It is not sales income.')}`,'','Save balance correction');break;
case'delete-coupon':{const c=state.records.coupons.find(c=>c.id===id);formModal('Delete '+c.id,'delete-coupon',notice('Remove this promotion from the active list? Previous orders keep their original discounts. Redemption history is retained.'),`data-id="${E(id)}"`,'Delete promotion');break;}
case'preview-staff':{requirePermission(state,'team');const p=state.records.staff.find(p=>p.id===id);state.previewStaff=p.id;state.previewRole=p.role;const first=modules.find(([k])=>can(state,k));navigate(first?'/admin/'+first[0]:'/admin');break;}
case'new-role':ownerOnly();formModal('Create staff role','new-role',field('Role name','name','','text','required'),'','Create role');break;
case'staff-permissions':{ownerOnly();const p=state.records.staff.find(p=>p.id===id);if(p.role==='Super Admin')throw Error('Owner access is protected.');formModal('Permissions · '+p.name,'staff-permissions',`${checkbox('Use role permissions (ignore individual overrides)','inherit',!p.customPermissions)}${permissionGrid(p.customPermissions||state.roles[p.role]||{})}`,`data-id="${id}"`,'Save staff permissions');dialog.style.width='min(960px,calc(100vw - 30px))';break;}
case'installer-back':state.installerStep=Math.max(0,state.installerStep-1);render();break;case'installer-connection':modal('Connection test preview',notice('No connection attempted. A real result will come from PDO on your PHP hosting server.'));break;
default:toast('This action is not available in the preview.');}
}catch(err){toast(err.message);}});

document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const kind=form.dataset.form,v=values(form),id=form.dataset.id,intent=e.submitter?.value;try{guardForm(kind,form);switch(kind){
case'owner-ai-verify':ownerOnly();throw Error('Owner verification is locked until the PHP authentication and email adapters are connected. No demo code can unlock it.');
case'welcome-popup':requirePermission(state,'content','edit');savePopup(state,v,fileOf(form,'popupImage'),intent);success('Welcome popup '+(intent==='Published'?'published':'draft saved'),'Content');break;
case'product-review':submitReview(state,id,v,[...(form.elements.namedItem('reviewPhotos')?.files||[])]);success('Your review is pending moderation.','Reviews');break;
case'review-moderation':{requirePermission(state,'products','edit');const r=state.reviews?.find(x=>x.id===id);if(!r||!['Pending','Published','Hidden','Removed'].includes(v.status)||!v.reason?.trim())throw Error('Choose a status and explain the decision.');if(v.status==='Removed'||r.status==='Removed')requirePermission(state,'products','delete');r.status=v.status;r.reply=(v.reply||'').trim();r.moderationReason=v.reason.trim();success('Review visibility and shop reply saved','Reviews');break;}
case'assistant-message':receiveCustomerMessage(state,v.message);state.assistantOpen=true;render();document.querySelector('.assistant-compose input')?.focus?.();break;
case'assistant-cart':{const c=chosen(v.variant);addCart(state.cart,state.products,c.id,c.size,numeric(v.qty,'Quantity',1),c.color);closeModal();render();toast('Added to your bag','/cart');break;}
case'support-reply':{const c=supportRecord(state,id);assertAssignee(state,c);if(!v.message.trim())throw Error('Write a reply.');c.mode='human';c.status='Assigned';c.messages.push({role:'staff',author:currentStaff(state).name,text:v.message.trim()});log('Preview reply added to '+id,'Support');render();break;}
case'support-assign':{const c=supportRecord(state,id);if(!can(state,'team','edit')&&c.assignee!==currentStaff(state)?.id)throw Error('Only the owner or assigned staff can reassign this conversation.');if(!eligibleStaff(state,c.channel).some(p=>p.id===v.staff))throw Error('That staff member is not authorized for this channel.');c.assignee=v.staff;c.mode='human';c.status='Assigned';log('Conversation '+id+' assigned','Support');render();break;}
case'variant-delete':{requirePermission(state,'inventory','delete');const v=variantFor(state.products.find(p=>p.id===id),form.dataset.size,form.dataset.color);if(v.onHand||v.reserved)throw Error('This variant still has stock.');v.archived=true;success('Zero-stock variant retired','Inventory');break;}
case'order-contact':{requirePermission(state,'orders','edit');const o=recordFor(state,'orders',id);if(v.phone&&!validPhone(v.phone))throw Error('Enter a valid phone number.');Object.assign(o,{customer:v.customer,phone:normalizePhone(v.phone),address:v.address,note:v.note});success('Order details updated','Orders');break;}
case'record-annotation':{const type=form.dataset.type;requirePermission(state,recordModule(type),'edit');const r=recordFor(state,type,id);r.note=v.note;r.displayReference=v.reference;success('Descriptive details updated; posted amounts retained',type);break;}
case'record-delete':archiveRecord(state,form.dataset.type,id,v.reason);success('Record moved to archive',form.dataset.type);break;
case'search':state.query=v.q.trim();state.category='All';navigate('/search?q='+encodeURIComponent(state.query));break;
case'coupon':{const c=v.code.trim().toUpperCase(),subtotal=cartTotals(state.cart,state.products).subtotal;if(c&&!state.records.coupons.some(p=>p.id===c&&p.status==='Active'&&!p.archived))throw Error('This promotion is unavailable or has been deleted.');if(!['AELVO10','SHIPFREE',''].includes(c))throw Error('Try AELVO10 or SHIPFREE in this preview.');if(c==='AELVO10'&&subtotal<2000)throw Error('AELVO10 needs at least ৳2,000 in eligible items.');state.coupon=c;render();toast(c?'Promo code applied':'Promo code cleared');break;}
case'otp':{const p=pendingOTP;if(!p)throw Error('Start verification again.');if(Date.now()>p.expires)throw Error('This code has expired. Request a new demo code.');if(p.attempts>=5)throw Error('Attempt limit reached. Request a new code.');p.attempts++;if(v.code!=='123456')throw Error('Incorrect demo code. Use 123456.');pendingOTP=null;clearInterval(otpTimer);if(p.purpose==='checkout'){state.verifiedCheckoutPhone=p.phone;closeModal();render();toast('Checkout number verified');}else if(p.purpose==='signup'){state.user={...p.payload,phone:p.phone,verified:true};state.authAccount={...state.user};navigate('/account');toast('Demo account created with verified phone');}else{state.user={...state.user,...p.payload,phone:p.phone,verified:true};if(state.authAccount)state.authAccount={...state.user};success('Primary phone verified and profile saved','Customer');}break;}
case'signin':{if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');const n=normalizePhone(v.phone);if(n==='01700007788')state.user={name:'Rahim Ahmed',phone:n,email:'rahim@example.com',verified:true};else if(state.authAccount?.phone===n)state.user={...state.authAccount};else throw Error('Use demo number 01700007788 or create a demo account.');navigate('/account');toast('Demo account opened');break;}
case'signup':if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email||''))throw Error('Enter a valid email address.');if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');otp(v.phone,'signup',{name:v.name,email:v.email.trim(),emailVerified:false});break;
case'profile':if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');if(normalizePhone(v.phone)!==state.user.phone)otp(v.phone,'profile',{name:v.name,email:v.email});else{state.user={...state.user,name:v.name,email:v.email};success('Profile saved','Customer');}break;
case'address':if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');{const i=Number(form.dataset.index);const a={label:v.label,address:v.address,phone:normalizePhone(v.phone)};if(i<0)state.addresses.push(a);else state.addresses[i]=a;success('Address saved','Customer');}break;
case'checkout':{const purchase=checkoutItems(state);storeCheckout();if(!v.demoConsent)throw Error('Confirm that this is a demo order.');if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');if(needsOTP(state.user,v.phone,state.verifiedCheckoutPhone))throw Error('Verify this delivery number before placing the order.');if(!purchase.length)throw Error('Your bag is empty.');for(const r of purchase){if(r.qty>available(state.products.find(p=>p.id===r.id),r.size,r.color))throw Error('Stock changed. Review your bag before continuing.');}if(v.payment==='bKash'&&!v.reference?.trim())throw Error('Enter a sample bKash reference for merchant review.');const t=cartTotals(purchase,state.products,state.buyNow?'':state.coupon,v.area==='Outside Dhaka'?130:80);const o={id:'AEL-'+(state.nextOrderId||1030),customer:v.name,phone:normalizePhone(v.phone),date:today(),status:v.payment==='bKash'?'Awaiting Advance Payment':'Pending',total:t.total,paid:0,source:'Online',items:structuredClone(purchase),discount:t.discount,shipping:t.shipping,address:v.address+', '+v.city,courier:'Not booked',note:v.notes,paymentMethod:v.payment};state.nextOrderId=(state.nextOrderId||1030)+1;for(const r of purchase)variantFor(state.products.find(p=>p.id===r.id),r.size,r.color).reserved+=r.qty;o.reserved=true;state.orders.unshift(o);if(v.payment==='bKash')state.records.payments.unshift({id:'REQ-'+o.id,order:o.id,method:'bKash',amount:Math.min(500,o.total),status:'Review required',settlement:'Not posted',reference:v.reference});state.lastOrder=o;if(state.buyNow)state.buyNow=null;else{state.cart=[];state.coupon='';}state.verifiedCheckoutPhone=null;state.checkoutDraft={};log('Demo order '+o.id+' placed','Orders');navigate('/confirmation');break;}
case'tracking':navigate('/tracking?id='+encodeURIComponent(v.id.trim().toUpperCase()));break;
case'customer-return':state.records.returns.unshift({id:'RMA-DEMO-'+(state.records.returns.length+1),order:v.order,customer:state.user?.name||'Demo customer',product:'Selected order item',qty:1,status:'Requested',restock:'Pending',refund:'Pending',amount:0,note:v.notes});success('Return request submitted for review','Returns');break;
case'contact':success('Demo message received — nothing was sent externally','Support');form.reset();break;
case'order-note':state.orders.find(o=>o.id===id).note=v.note;success('Order note saved','Orders');break;
case'order-status':{const o=state.orders.find(o=>o.id===id);if(o.status==='Cancelled'&&v.status!=='Cancelled')throw Error('Create a new order instead of reopening a cancelled reservation.');if(o.status==='Awaiting Advance Payment'&&!['Awaiting Advance Payment','Cancelled'].includes(v.status)&&o.paid<Math.min(500,o.total))throw Error('Verify the required advance before fulfilment.');if(o.status==='Delivered'&&v.status!=='Delivered')throw Error('A delivered order needs a return or correction workflow.');if(o.reserved&&v.status==='Cancelled'){for(const r of o.items){const st=variantFor(state.products.find(p=>p.id===r.id),r.size,r.color);st.reserved=Math.max(0,st.reserved-r.qty);}o.reserved=false;}if(o.reserved&&v.status==='Delivered'){for(const r of o.items){const st=variantFor(state.products.find(p=>p.id===r.id),r.size,r.color);if(st.onHand<r.qty)throw Error('Insufficient physical stock.');}for(const r of o.items){const st=variantFor(state.products.find(p=>p.id===r.id),r.size,r.color);st.onHand-=r.qty;st.reserved=Math.max(0,st.reserved-r.qty);state.records.movements.push({id:'MOV-'+Date.now()+'-'+r.id,product:variantLabel(state.products.find(p=>p.id===r.id),r.size,r.color),productId:r.id,color:r.color,type:'Sale',qty:-r.qty,reference:o.id,date:today()});}o.reserved=false;}o.status=v.status;success('Order status updated: '+v.status,'Orders');break;}
case'order-payment':{const o=state.orders.find(o=>o.id===id),amount=numeric(v.amount,'Amount',.01);if(!v.verified)throw Error('Review and confirm the sample merchant receipt.');codBalance(o.total,o.paid+amount);if(state.records.payments.some(p=>p.reference===v.reference))throw Error('That payment reference has already been used.');o.paid+=amount;if(o.status==='Awaiting Advance Payment'&&o.paid>=Math.min(500,o.total))o.status='Processing';state.accounts[v.account]+=amount;state.records.payments.unshift({id:'PAY-DEMO-'+Date.now(),order:o.id,method:v.account,amount,status:'Verified',settlement:'Received',reference:v.reference});success('Verified demo payment recorded','Payments');break;}
case'courier-book':{const o=state.orders.find(o=>o.id===id);if(o.courier!=='Not booked')throw Error('This order already has a consignment.');o.courier='DEMO-'+id;o.status='Courier Booked';o.address=v.address;success('Demo consignment created; dispatch is still pending','Courier');break;}
case'manual-add':{const c=chosen(v.variant||id+'::'+v.size);addCart(state.manual,state.products,id,c.size,Number(v.qty),c.color);}success('Item added to manual sale','Sales');break;
case'manual-sale':{if(!state.manual.length)throw Error('Add at least one item.');const subtotal=state.manual.reduce((a,r)=>a+state.products.find(p=>p.id===r.id).price*r.qty,0),discount=numeric(v.discount,'Discount'),total=subtotal-discount,received=numeric(v.received,'Received');if(discount>subtotal)throw Error('Discount exceeds the subtotal.');if(intent!=='draft'&&received<total)throw Error('The received amount is less than the sale total.');for(const r of state.manual)if(r.qty>available(state.products.find(p=>p.id===r.id),r.size,r.color))throw Error('There is not enough available stock.');const sale={id:'MS-DEMO-'+(state.nextSaleId||19),customer:v.customer||'Walk-in customer',phone:'',date:today(),status:intent==='draft'?'Draft':'Delivered',total,paid:intent==='draft'?0:total,source:'Manual',items:structuredClone(state.manual),discount,shipping:0,address:'Walk-in',courier:'Not required'};state.nextSaleId=(state.nextSaleId||19)+1;if(intent!=='draft'){for(const r of state.manual){variantFor(state.products.find(p=>p.id===r.id),r.size,r.color).onHand-=r.qty;state.records.movements.push({id:'MOV-'+Date.now()+'-'+r.id,product:variantLabel(state.products.find(p=>p.id===r.id),r.size,r.color),productId:r.id,color:r.color,type:'Manual sale',qty:-r.qty,reference:sale.id,date:today()});}state.accounts[v.account]+=total;state.records.payments.unshift({id:'PAY-'+sale.id,order:sale.id,method:v.account,amount:total,status:'Verified',settlement:'Received'});}state.orders.unshift(sale);state.manual=[];success(intent==='draft'?'Sale draft saved':'Demo sale completed; change '+money(received-total),'Sales');navigate('/admin/orders/'+sale.id);break;}
case'record':saveRecord(form,v);break;
case'transfer':{const n=numeric(v.amount,'Amount',.01);if(!v.explanation?.trim())throw Error('Add an explanation for the transfer.');if(!(v.from in state.accounts)||!(v.to in state.accounts)||v.from===v.to)throw Error('Choose two different accounts.');if(n>state.accounts[v.from])throw Error('Insufficient available funds.');const document=attach(fileOf(form,'document')),changes=[{account:v.from,before:state.accounts[v.from],after:state.accounts[v.from]-n},{account:v.to,before:state.accounts[v.to],after:state.accounts[v.to]+n}];changes.forEach(c=>state.accounts[c.account]=c.after);recordFinance(state,'Transfer',v,changes,document);success(money(n)+' transferred from '+v.from+' to '+v.to,'Accounts');break;}
case'add-funds':{if(!v.explanation?.trim())throw Error('Add an explanation for these funds.');if(!(v.account in state.accounts))throw Error('Choose a valid account.');const n=numeric(v.amount,'Amount',.01),document=attach(fileOf(form,'document')),before=state.accounts[v.account];state.accounts[v.account]+=n;recordFinance(state,'Add funds',v,[{account:v.account,before,after:state.accounts[v.account]}],document);success('Non-sales funds added to '+v.account,'Accounts');break;}
case'balance-adjust':{if(!v.explanation?.trim())throw Error('Explain the balance correction.');if(!(v.account in state.accounts))throw Error('Choose a valid account.');const after=numeric(v.balance,'Balance'),before=state.accounts[v.account],document=attach(fileOf(form,'document'));if(after===before)throw Error('The balance is unchanged.');state.accounts[v.account]=after;recordFinance(state,'Balance correction',v,[{account:v.account,before,after}],document);success('Balance corrected with an audit entry','Accounts');break;}
case'inventory-adjust':{const p=state.products.find(p=>p.id===id),st=variantFor(p,form.dataset.size,form.dataset.color),next=numeric(v.onHand,'Counted stock');if(!Number.isInteger(next)||next<st.reserved)throw Error('Use whole units and keep at least the reserved quantity.');if(!v.reason?.trim())throw Error('Explain the stock correction.');const before=st.onHand;if(next===before)throw Error('The count is unchanged.');st.onHand=next;state.records.movements.push({id:'MOV-'+Date.now(),productId:p.id,product:variantLabel(p,st.size,st.color),color:st.color,type:'Stock correction',qty:next-before,reference:'ADJ-'+Date.now(),date:today(),note:before+' → '+next+'. '+v.reason});success('Stock count corrected with history','Inventory');break;}
case'delete-coupon':{const c=state.records.coupons.find(c=>c.id===id);if(!c)throw Error('Promotion already deleted.');state.deletedCoupons??=[];state.deletedCoupons.push({...c,deletedAt:new Date().toISOString()});state.records.coupons=state.records.coupons.filter(c=>c.id!==id);if(state.coupon===id)state.coupon='';success('Promotion deleted; past order discounts retained','Marketing');break;}
case'new-role':{ownerOnly();const name=v.name.trim();if(!name||name==='Super Admin'||Object.hasOwn(state.roles,name))throw Error('Choose a unique staff role name.');state.roles[name]={};state.permissionRole=name;success('Role created; grant its permissions','Access');navigate('/admin/team/roles');break;}
case'permissions':ownerOnly();state.roles[state.permissionRole||'Entry Staff']=readPermissions(v);success('Role permissions saved','Access');break;
case'staff-permissions':{ownerOnly();const p=state.records.staff.find(p=>p.id===id);if(p.role==='Super Admin')throw Error('Owner access is protected.');if(v.inherit)delete p.customPermissions;else p.customPermissions=readPermissions(v);success('Staff permissions saved','Access');break;}
case'advance-review':{if(!v.checked)throw Error('Confirm that merchant evidence was checked.');const p=state.records.payments.find(p=>p.id==='REQ-0102');if(p.status==='Verified')throw Error('This payment has already been verified.');if(v.decision==='Verify received payment'){p.status='Verified';p.settlement='Received';p.reference=v.reference;state.accounts.bKash+=p.amount;let o=state.orders.find(o=>o.id===p.order);if(!o){o={id:p.order,customer:'Demo advance customer',phone:'01700009999',date:today(),status:'Processing',total:3500,paid:0,source:'Online',items:[],discount:0,shipping:0,address:'Dhaka',courier:'Not booked'};state.orders.unshift(o);}o.paid+=p.amount;o.status='Processing';}else p.status='Rejected';success('Advance review saved','Payments');break;}
case'settlement':{const n=numeric(v.amount,'Bank receipt',0);if(n!==14700)throw Error('The '+money(14700-n)+' variance must be resolved. Match the sample receipt to ৳14,700 before posting.');if(state.settlementPosted)throw Error('This settlement has already been posted.');if(!v.note.trim())throw Error('Explain how the discrepancy was resolved.');state.settlementPosted=true;state.accounts.Bank+=n;success('Demo settlement posted once','Accounts');break;}
case'inspect-return':{const r=state.records.returns.find(r=>r.id===id),qty=numeric(v.qty,'Received quantity');if(!Number.isInteger(qty))throw Error('Return quantities must be whole units.');if(qty>r.qty)throw Error('Quantity exceeds the requested return.');r.received=qty;r.status=v.condition==='Sellable'&&qty===r.qty?'Inspection passed':'Inspection review';r.inspectionNote=v.note;success('Return inspection recorded','Returns');break;}
case'restock-return':{const r=state.records.returns.find(r=>r.id===id);if(r.restock==='Completed')throw Error('This return has already been restocked.');if(r.status!=='Inspection passed')throw Error('Inspection must pass before restocking.');const c=chosen(v.variant);if(c.product.name!==r.product)throw Error('Restock the inspected product only.');c.variant.onHand+=r.qty;r.restock='Completed';state.records.movements.push({id:'MOV-'+Date.now(),product:variantLabel(c.product,c.size,c.color),productId:c.id,color:c.color,size:c.size,type:'Return restock',qty:r.qty,reference:r.id,date:today()});success('Sellable return restocked once','Inventory');break;}
case'refund-review':{const r=state.records.returns.find(r=>r.id===id),n=numeric(v.amount,'Refund',.01);if(r.status!=='Inspection passed')throw Error('Complete inspection before refund approval.');if(n>r.amount)throw Error('Refund exceeds the verified refundable amount.');if(r.refund==='Approved')throw Error('This refund has already been approved.');r.refund='Approved';r.refundAmount=n;r.refundAccount=v.account;success('Refund approved; payment has not been executed','Refunds');break;}
case'customer-note':state.records.customers.find(c=>c.id===id).note=v.note;success('Customer note saved','Customers');break;
case'risk-review':if(!v.reviewed)throw Error('Review the evidence before saving.');state.saved.risk=v;success('Review saved: '+v.action,'Customer review');break;
case'config':{const section=form.dataset.section;if(section==='settings-theme'&&(!/^#[0-9a-f]{6}$/i.test(v.accent)||!/^#[0-9a-f]{6}$/i.test(v.surface)))throw Error('Choose valid theme colours.');if(section==='settings-assistant'){state.support.enabled=!!v.enabled;for(const c of ['Website','WhatsApp','Messenger'])state.support.channels[c]=!!v['channel'+c];}if(section==='seo-robots'&&/Disallow:\s*\/(?:\r?\n|$)/i.test(v.robots))throw Error('This draft blocks the entire site. Review the disallow-all rule before saving.');if(v.slug&&!validSlug(v.slug))throw Error('Use a lowercase, unique, non-reserved slug.');if(section==='seo-verification'&&Object.values(v).some(x=>typeof x==='string'&&/[<>]/.test(x)))throw Error('Use verification tokens only, without HTML.');state.saved[section]=v;if(section==='settings-general'){for(const k of ['name','currency','timezone','language','orderPrefix','invoicePrefix'])state.settings[k]=v[k]||state.settings[k];}success('Configuration saved as a demo draft','Settings');break;}
case'page-editor':{const p=state.records.pages.find(p=>p.id===id);if(!validSlug(v.slug))throw Error('Use a lowercase, non-reserved slug.');if(state.records.pages.some(x=>x.id===v.slug&&x.id!==id))throw Error('This slug already belongs to another page.');if(id!==v.slug&&p.status==='Published'){validateRedirect('/'+id,'/'+v.slug,state.records.redirects);state.records.redirects.push({id:'RED-'+Date.now(),from:'/'+id,to:'/'+v.slug,type:'301'});}Object.assign(p,{id:v.slug,name:v.name,content:v.content,button:v.button,destination:v.destination,alt:v.alt,status:intent==='publish'?'Published':'Draft'});success('Page '+(intent==='publish'?'published in demo':'draft saved'),'Content');navigate('/admin/content/'+p.id);break;}
case'banner':saveBanner(state,v,form,intent);success('Banner '+(intent==='Published'?'published in demo':'draft saved'),'Content');break;
case'role-permissions':state.saved.rolePermissions=v;success('Demo role permissions saved','Access');break;
case'delete-redirect':state.records.redirects=state.records.redirects.filter(r=>r.id!==id);success('Redirect removed','SEO');break;
case'installer':if(state.installerStep===4){const password=formInput('password',form).value;if(password!==formInput('confirm',form).value)throw Error('Passwords do not match.');if(!/[a-z]/.test(password)||!/[A-Z]/.test(password)||!/[0-9]/.test(password)||password.length<12)throw Error('Use 12+ characters with uppercase, lowercase and a number.');}state.installerStep++;if(state.installerStep>=10)state.installerDone=true;render();window.scrollTo(0,0);break;
default:throw Error('This form is not available.');}
}catch(err){fail(form,err.message);}});

function saveRecord(form,v){const type=form.dataset.type,id=form.dataset.id;const list=type==='products'?state.products:state.records[type];let r=list?.find(x=>x.id===id);switch(type){
case'products':{const data=readProduct(form,v,r);if(r)Object.assign(r,data);else state.products.push({id:'product-'+Date.now(),tag:'New arrival',...data});break;}
case'stock':{const c=chosen(v.variant),qty=numeric(v.qty,'Quantity',1);if(!Number.isInteger(qty))throw Error('Stock quantities must be whole units.');if(!can(state,'inventory','edit')&&v.type!=='Purchase receipt')throw Error('This role can receive purchased stock only.');const negative=v.type==='Damage / write-off',signed=negative?-qty:qty;if(negative&&qty>c.variant.onHand-c.variant.reserved)throw Error('Insufficient unreserved stock for this movement.');if(v.intent==='post'){if(state.records.movements.some(m=>m.reference===v.reference&&m.product===variantLabel(c.product,c.size,c.color)))throw Error('A movement with this reference already exists for this variant.');c.variant.onHand+=signed;state.records.movements.push({id:'MOV-'+Date.now(),product:variantLabel(c.product,c.size,c.color),productId:c.id,color:c.color,size:c.size,type:v.type,qty:signed,reference:v.reference,date:today(),note:v.note});}else{state.saved.stockDrafts??=[];state.saved.stockDrafts.push(v);}success(v.intent==='post'?'Stock movement posted':'Stock draft saved; quantities unchanged','Inventory');return;}
case'purchases':{const slip=attach(fileOf(form,'purchaseSlip'),true);const qty=numeric(v.qty,'Quantity',1),cost=numeric(v.cost,'Cost'),discount=numeric(v.discount,'Discount'),base=qty*cost;if(!Number.isInteger(qty))throw Error('Purchase quantities must be whole units.');if(discount>base)throw Error('Discount exceeds purchase subtotal.');state.records.purchases.unshift({id:'PO-DEMO-'+(state.records.purchases.length+1),supplier:v.supplier,total:base-discount+numeric(v.shipping,'Shipping')+numeric(v.other,'Other costs'),paid:0,status:'Draft',date:today(),variant:v.variant,qty,slip});break;}
case'suppliers':if(r)Object.assign(r,{name:v.name,phone:v.phone,notes:v.notes});else state.records.suppliers.push({id:'SUP-'+Date.now(),name:v.name,phone:v.phone,notes:v.notes,due:0,status:'Active'});break;
case'expenses':{const amount=numeric(v.amount,'Amount',.01);if(r?.status==='Posted')throw Error('Posted entries cannot be overwritten.');if(v.status==='Posted'&&amount>state.accounts[v.account])throw Error('Insufficient available funds.');if(v.status==='Posted')state.accounts[v.account]-=amount;if(r)Object.assign(r,{category:v.category,amount,account:v.account,status:v.status,date:v.date});else state.records.expenses.push({id:'EXP-'+Date.now(),category:v.category,amount,account:v.account,status:v.status,date:v.date});break;}
case'customers':if(!validPhone(v.phone))throw Error('Enter a valid Bangladesh mobile number.');if(r){Object.assign(r,{name:v.name,phone:normalizePhone(v.phone)});break;}state.records.customers.push({id:'CUS-'+Date.now(),name:v.name,phone:normalizePhone(v.phone),type:'Contact',orders:0,delivered:0,status:'Not account-verified'});break;
case'coupons':{const limit=numeric(v.limit,'Usage limit',1),percentage=numeric(v.value,'Discount');if(percentage>100)throw Error('Percentage cannot exceed 100.');if(v.start&&v.end&&v.end<v.start)throw Error('End date must be after start date.');if(state.records.coupons.some(c=>c.id===v.id.toUpperCase()&&c.id!==id))throw Error('That promotion code already exists.');if(r&&limit<r.used)throw Error('The limit cannot be less than existing redemptions.');const data={...v,id:v.id.toUpperCase(),value:percentage,cap:numeric(v.cap,'Cap'),min:numeric(v.min,'Minimum'),limit,perCustomer:Number(v.perCustomer),used:r?.used||0};if(r)Object.assign(r,data);else state.records.coupons.push(data);break;}
case'pages':if(!validSlug(v.slug))throw Error('Use a lowercase, non-reserved slug.');if(state.records.pages.some(p=>p.id===v.slug))throw Error('That slug is already used.');state.records.pages.push({id:v.slug,name:v.name,status:'Draft',content:''});break;
case'staff':{ownerOnly();if(!validPhone(v.phone))throw Error('Enter a valid staff mobile number.');if(state.records.staff.some(x=>x.id!==id&&(x.phone===normalizePhone(v.phone)||x.email.toLowerCase()===v.email.toLowerCase())))throw Error('A staff profile already uses that phone or email.');const data={...v,phone:normalizePhone(v.phone)};if(r?.role==='Super Admin'){delete data.role;delete data.status;}else if(!Object.hasOwn(state.roles,v.role))throw Error('Choose an existing role.');if(r)Object.assign(r,data);else state.records.staff.push({id:'USR-'+Date.now(),...data});break;}
case'redirects':validateRedirect(v.from,v.to,state.records.redirects.filter(x=>!x.archived&&x.id!==id));if(r)Object.assign(r,v);else state.records.redirects.push({id:'RED-'+Date.now(),...v});break;
case'returns':state.records.returns.push({id:'RMA-'+Date.now(),order:v.order,product:v.product,qty:numeric(v.qty,'Quantity',1),amount:numeric(v.amount,'Refundable amount'),status:'Requested',restock:'Pending',refund:'Pending'});break;
default:throw Error('Unsupported record type.');}
success('Record saved',type);}

function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample file downloaded');}
function downloadCSV(type){let rows;if(type==='sales')rows=[['Order','Date','Status','Gross','Discount','Refund','Net'],...reportRows];else if(type==='profit')rows=[['Line','BDT'],['Net revenue',17500],['Net COGS',11000],['Gross profit',6500],['Expenses',2500],['Net profit',4000]];else{let records=type==='orders'?state.orders:type==='products'?state.products:type==='audit'?state.audit:type==='inventory'?state.products.flatMap(p=>p.variants.map(v=>({product:p.name,size:v.size,onHand:v.onHand,reserved:v.reserved,available:v.onHand-v.reserved}))):state.records[type];if(!records?.length)throw Error('No sample rows to export for this report.');const keys=Object.keys(records[0]).filter(k=>!['image','items','variants','description'].includes(k));rows=[keys,...records.map(r=>keys.map(k=>r[k]??''))];}const safe=c=>{const str=String(c??'');return '"'+(/^[=+\-@\t\r]/.test(str)?"'":'')+str.replaceAll('"','""')+'"';};download('aelvo-'+type+'-demo.csv','text/csv;charset=utf-8','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'));}

function filterTable(name){const q=document.querySelector(`[data-table-search="${name}"]`)?.value.toLowerCase()||'',status=document.querySelector(`[data-table-status="${name}"]`)?.value||'';document.querySelector(`[data-filter-table="${name}"] table`)?.querySelectorAll('tbody tr').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q)||(!!status&&!row.textContent.includes(status));});}

document.addEventListener('input',e=>{const t=e.target;if(t.id==='header-query'){state.headerQuery=t.value;const results=document.querySelector('#header-search-results');if(results)results.innerHTML=searchResults(state,t.value);}if(t.matches('[data-table-search]')){filterTable(t.dataset.tableSearch);}if(t.id==='admin-search'&&t.value.trim().length>1){const matches=adminNav.filter(n=>n[1].toLowerCase().includes(t.value.toLowerCase()));if(matches.length&&e.inputType==='insertLineBreak')navigate('/admin/'+matches[0][0]);}if(t.id==='manual-search')document.querySelectorAll('#manual-products>.card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.matches('[data-seo-live]')){const node=document.querySelector('#seo-live-'+t.dataset.seoLive);if(node)node.textContent=t.value;}if(t.matches('[data-banner-live]')){const node=document.querySelector('#banner-live-'+t.dataset.bannerLive);if(node)node.textContent=t.value;}if(t.name==='phone'&&t.closest('#checkout-form')){storeCheckout();const n=needsOTP(state.user,t.value,state.verifiedCheckoutPhone),box=document.querySelector('#verification-state');box.innerHTML=localizeMarkup(`<span class="small"><span class="badge ${n?'outline':''}">${n?'Verification required':'Phone verified'}</span></span>${button(n?'Verify number':'Verified','checkout-otp',n?'':'disabled','btn small secondary')}`,state);}if(['received','discount'].includes(t.name)&&t.closest('[data-form="manual-sale"]')){const f=t.form,sub=state.manual.reduce((a,r)=>a+state.products.find(p=>p.id===r.id).price*r.qty,0),total=sub-Number(f.elements.discount.value||0),change=Number(f.elements.received.value||0)-total;const node=document.querySelector('#manual-change');if(node)node.textContent=change>=0?money(change):'Short '+money(-change);}});
document.addEventListener('change',e=>{const t=e.target;if(t.type==='file'&&t.closest?.('.field')){const label=t.closest('.field');let feedback=label.querySelector('[data-file-feedback]');if(!feedback){feedback=document.createElement('small');feedback.dataset.fileFeedback='';feedback.className='file-feedback';label.append(feedback);}feedback.textContent=t.files?.length?[...t.files].map(f=>f.name).join(', ')+' · Selected':'No file selected';label.classList.toggle('file-selected',!!t.files?.length);}if(t.id==='sort-products'){state.sort=t.value;render();}if(t.id==='preview-role'){state.previewRole=t.value;state.previewStaff=null;const first=modules.find(([id])=>can(state,id));navigate(first?'/admin/'+first[0]:'/admin');}if(t.id==='balance-account'){const input=t.form?.elements.namedItem('balance');if(input)input.value=state.accounts[t.value];}if(t.id==='permission-role'){state.permissionRole=t.value;render();}if(t.type==='file'&&t.closest('[data-colour-row]')){const row=t.closest('[data-colour-row]'),box=row.querySelector('[data-colour-previews]');box.innerHTML='';for(const file of [...t.files]){if(!file.type.startsWith('image/'))continue;const img=document.createElement('img');img.src=URL.createObjectURL(file);img.alt='Selected colour photo';img.onload=()=>URL.revokeObjectURL(img.src);box.append(img);}}if(t.matches('[data-table-status]')){filterTable(t.dataset.tableStatus);}if(t.name==='area'&&t.closest('#checkout-form')){storeCheckout();document.querySelector('#checkout-totals').innerHTML=localizeMarkup(totalsHTML(checkoutView(state),t.value==='Outside Dhaka'?130:80),state);}if(t.name==='payment'){const b=document.querySelector('#advance-fields');if(b)b.hidden=t.value!=='bKash';storeCheckout();}if(t.type==='file'&&t.name==='photos'){const p=document.querySelector('#upload-preview');if(p){p.innerHTML='';for(const f of [...t.files].slice(0,4)){if(!f.type.startsWith('image/'))continue;const img=document.createElement('img');img.alt='Return evidence preview';const url=URL.createObjectURL(f);img.src=url;img.onload=()=>URL.revokeObjectURL(url);p.append(img);}}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.searchOpen){state.searchOpen=false;render();}else if(state.assistantOpen){state.assistantOpen=false;render();}}if(e.target.id==='admin-search'&&e.key==='Enter'){e.preventDefault();const matches=adminNav.filter(n=>n[1].toLowerCase().includes(e.target.value.toLowerCase()));if(matches.length)navigate('/admin/'+matches[0][0]);else toast('No matching module.');}});
document.addEventListener('click',e=>{if(e.target.closest('a[href^="#/"]')&&dialog.open)closeModal();});
document.addEventListener('focusout',e=>{const t=e.target;if(t.name==='phone'&&validPhone(t.value))t.value=normalizePhone(t.value);});
if(!location.hash)history.replaceState(null,'','#/');render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_preview_cart',title:'Read AELVO demo cart',description:'Read items and totals in this frontend preview. No real order is created.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {items:state.cart,totals:cartTotals(state.cart,state.products,state.coupon)};}},{name:'add_preview_cart_item',title:'Add AELVO demo cart item',description:'Add an available variant to the visible demo shopping bag. Does not purchase or charge.',inputSchema:{type:'object',properties:{productId:{type:'string'},size:{type:'string'},quantity:{type:'integer',minimum:1}},required:['productId','size','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute(v){if(!v||typeof v.productId!=='string'||typeof v.size!=='string'||!Number.isInteger(v.quantity))throw Error('Invalid cart input.');addCart(state.cart,state.products,v.productId,v.size,v.quantity);render();return {added:true,items:state.cart.length};}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
export {state};
